import React, { useState, useEffect } from 'react';
import { NavLink, Outlet } from 'react-router-dom';
import axios from 'axios';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTachometerAlt, faUserGraduate, faChalkboardTeacher, faMoneyBillWave, faCog, faQuestionCircle, faChevronLeft, faChevronRight, faSearch, faBell, faEnvelope, faChevronDown, faSun, faMoon, faCalendarAlt, faClipboardList } from '@fortawesome/free-solid-svg-icons';
import './../assets/css/dashboard-content.css';

const AdminDashboard = () => {
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [totalStudents, setTotalStudents] = useState(0);
  const [totalTeachers, setTotalTeachers] = useState(0);
  const [upcomingEventsCount, setUpcomingEventsCount] = useState(0);
  const [activeCoursesCount, setActiveCoursesCount] = useState(0);
  const [currentDate, setCurrentDate] = useState('');

  useEffect(() => {
    fetchSummaryData();
    const formatDate = () => {
      const date = new Date();
      const options = { weekday: 'long', month: 'long', day: 'numeric' };
      return date.toLocaleDateString('en-US', options);
    };
    setCurrentDate(formatDate());
    const timer = setInterval(() => {
      setCurrentDate(formatDate());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const toggleSidebar = () => {
    setIsCollapsed(!isCollapsed);
  };

  const toggleDropdown = () => {
    setIsDropdownOpen(!isDropdownOpen);
  };

  const toggleDarkMode = () => {
    setIsDarkMode(!isDarkMode);
  };

  const fetchSummaryData = async () => {
    try {
      const token = localStorage.getItem('token');

      const studentsRes = await axios.get('http://localhost:5000/api/students', {
        headers: { 'x-auth-token': token }
      });
      setTotalStudents(studentsRes.data.length);

      const teachersRes = await axios.get('http://localhost:5000/api/teachers', {
        headers: { 'x-auth-token': token }
      });
      setTotalTeachers(teachersRes.data.length);

      setUpcomingEventsCount(12);
      setActiveCoursesCount(45);

    } catch (err) {
      console.error(err);
    }
  };

  const currentMonth = 'September 2025';
  const daysOfWeek = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];
  const calendarDays = [...Array(30)].map((_, i) => i + 1);

  return (
    <div className={`dashboard-container ${isDarkMode ? 'dark-mode' : ''}`}>
      {/* Sidebar */}
      <aside className={`sidebar ${isCollapsed ? 'collapsed' : ''}`}>
        <div className="sidebar-header">
          <h1 className="app-logo">ECA</h1>
          <button className="collapse-btn" onClick={toggleSidebar}>
            <FontAwesomeIcon icon={isCollapsed ? faChevronRight : faChevronLeft} />
          </button>
        </div>
        <nav className="sidebar-menu">
          <NavLink to="/admin-dashboard" end className="sidebar-menu-item" activeClassName="selected">
            <FontAwesomeIcon icon={faTachometerAlt} />
            {!isCollapsed && <span>Dashboard</span>}
          </NavLink>
          <NavLink to="/admin-dashboard/students" className="sidebar-menu-item" activeClassName="selected">
            <FontAwesomeIcon icon={faUserGraduate} />
            {!isCollapsed && <span>Student Management</span>}
          </NavLink>
          <NavLink to="/admin-dashboard/teachers" className="sidebar-menu-item" activeClassName="selected">
            <FontAwesomeIcon icon={faChalkboardTeacher} />
            {!isCollapsed && <span>Teacher Management</span>}
          </NavLink>
          <NavLink to="/admin-dashboard/fees" className="sidebar-menu-item" activeClassName="selected">
            <FontAwesomeIcon icon={faMoneyBillWave} />
            {!isCollapsed && <span>Fee Management</span>}
          </NavLink>
          <NavLink to="/admin-dashboard/courses" className="sidebar-menu-item" activeClassName="selected">
            <FontAwesomeIcon icon={faCog} />
            {!isCollapsed && <span>Courses</span>}
          </NavLink>
        </nav>
        <div className="sidebar-footer">
          <div className="sidebar-footer-item">
            <FontAwesomeIcon icon={faQuestionCircle} />
            {!isCollapsed && <span>Help & Support</span>}
          </div>
          <button className="logout-btn">
            <FontAwesomeIcon icon={faSignOutAlt} />
            {!isCollapsed && <span>Logout</span>}
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className={`main-content ${isCollapsed ? 'full-width' : ''}`}>
        {/* Header Section */}
        <header className="dashboard-header-main">
          <div className="search-bar-container">
            <input type="text" placeholder="Search" className="search-input" />
            <FontAwesomeIcon icon={faSearch} className="search-icon" />
          </div>
          <div className="header-right">
            <FontAwesomeIcon icon={faEnvelope} className="header-icon" />

            {/* Dark Mode Toggle Button */}
            <button className="theme-toggle-btn" onClick={toggleDarkMode}>
              <FontAwesomeIcon icon={isDarkMode ? faSun : faMoon} />
            </button>

            <div className="profile-dropdown-container">
              <div className="profile-trigger" onClick={toggleDropdown}>
                <img src="/path/to/profile-pic.png" alt="Profile" className="profile-pic-header" />
                <div className="profile-info-header">
                  <p className="profile-name-header">Diane Nguyen</p>
                  <p className="profile-role-header">2nd year</p>
                </div>
                <FontAwesomeIcon icon={faChevronDown} className="dropdown-arrow" />
              </div>
              {isDropdownOpen && (
                <div className="dropdown-menu">
                  <NavLink to="/admin-dashboard/profile" className="dropdown-item">Profile</NavLink>
                  <NavLink to="/admin-dashboard/change-password" className="dropdown-item">Change Password</NavLink>
                  <button className="dropdown-item">Logout</button>
                </div>
              )}
            </div>
          </div>
        </header>

        {/* Dashboard Content */}
        <div className="dashboard-content">
          <div className="welcome-banner">
            <div className="banner-content">
              <p className="banner-date">{currentDate}</p>
              <h2 className="banner-title">Welcome back, Diane!</h2>
              <p className="banner-goal">You've finished <span className="highlight-goal">85%</span> of your weekly goal!</p>
            </div>
            <div className="banner-illustration">
              <div className="graduation-cap"></div>
            </div>
          </div>

          <div className="stats-grid">
            <div className="stat-card">
              <FontAwesomeIcon icon={faUserGraduate} className="stat-icon" />
              <div className="stat-info">
                <h3>Total Students</h3>
                <p className="stat-value">{totalStudents}</p>
              </div>
            </div>
            <div className="stat-card">
              <FontAwesomeIcon icon={faChalkboardTeacher} className="stat-icon" />
              <div className="stat-info">
                <h3>Total Teachers</h3>
                <p className="stat-value">{totalTeachers}</p>
              </div>
            </div>
            <div className="stat-card">
              <FontAwesomeIcon icon={faCalendarAlt} className="stat-icon" />
              <div className="stat-info">
                <h3>Upcoming Events</h3>
                <p className="stat-value">{upcomingEventsCount}</p>
              </div>
            </div>
            <div className="stat-card">
              <FontAwesomeIcon icon={faClipboardList} className="stat-icon" />
              <div className="stat-info">
                <h3>Active Courses</h3>
                <p className="stat-value">{activeCoursesCount}</p>
              </div>
            </div>
          </div>

          <div className="dashboard-grid">
            <div className="calendar-card">
              <div className="card-header">
                <h3>{currentMonth}</h3>
                <div className="calendar-nav">
                  <FontAwesomeIcon icon={faArrowLeft} />
                  <FontAwesomeIcon icon={faArrowRight} />
                </div>
              </div>
              <div className="calendar-grid">
                {daysOfWeek.map(day => (
                  <div key={day} className="calendar-day-header">{day}</div>
                ))}
                {calendarDays.map((day) => (
                  <div key={day} className={`calendar-day ${[14].includes(day) ? 'active' : ''} ${[15, 20].includes(day) ? 'highlighted-day' : ''}`}>
                    {day}
                  </div>
                ))}
              </div>
              <div className="quick-actions">
                <button className="add-event-btn">Add New Event</button>
                <button className="announcement-btn">Send Announcement</button>
              </div>
            </div>

            <div className="events-card">
              <h3>Upcoming Events</h3>
              <ul className="event-list">
                <li>
                  <span className="event-detail">May 10th - Parent-Teacher Conference <br/><span className="event-description">Schedule meetings with parents</span></span>
                  <span className="event-tag event">Event</span>
                </li>
                <li>
                  <span className="event-detail">May 15th - Science Fair Judging <br/><span className="event-description">Evaluate student projects in the gymnasium</span></span>
                  <span className="event-tag event">Event</span>
                </li>
                <li>
                  <span className="event-detail">May 20th - Midterm Exams Begin <br/><span className="event-description">All core subjects</span></span>
                  <span className="event-tag exam">Exam</span>
                </li>
                <li>
                  <span className="event-detail">May 27th - Memorial Day <br/><span className="event-description">School Closed</span></span>
                  <span className="event-tag holiday">Holiday</span>
                </li>
                 <li>
                  <span className="event-detail">June 5th - Athletic Awards Ceremony <br/><span className="event-description">Recognizing student athletes</span></span>
                  <span className="event-tag event">Event</span>
                </li>
              </ul>
            </div>
          </div>

          <div className="charts-grid">
            <div className="chart-card">
              <h3>Enrollment by Grade</h3>
              <div className="bar-chart-placeholder">
                <div className="bar grade-9"></div>
                <div className="bar grade-10"></div>
                <div className="bar grade-11"></div>
                <div className="bar grade-12"></div>
              </div>
              <div className="chart-legend">
                <span>Grade 9</span>
                <span>Grade 10</span>
                <span>Grade 11</span>
                <span>Grade 12</span>
              </div>
            </div>
            <div className="chart-card">
              <h3>Teacher Distribution</h3>
              <div className="donut-chart-placeholder">
                <div className="donut-segment math"></div>
                <div className="donut-segment science"></div>
                <div className="donut-segment humanities"></div>
                <div className="donut-segment arts"></div>
                <div className="donut-segment physical-ed"></div>
              </div>
              <div className="chart-legend-bottom">
                <span>Mathematics</span>
                <span>Science</span>
                <span>Humanities</span>
                <span>Arts</span>
                <span>Physical Education</span>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

export default AdminDashboard;
